 <!--banner section--><div class="banner_wrapper">  <!--carousel section-->  <div class="inner-banner">      <image class="img-responsive" src="images/slider-03.jpg" alt="">      <div class="banner-text"><h1>Create New Password</h1></div>    </div></div>  <!--about section--><div class="about_wrappers" >         <div class="inner-body">      <div class="container">		<div class="register-body">      		<div id='response-success'></div>             <div id='response-error'></div>                   <form  id="form111" method="post" enctype="multipart/form-data" >                <input type='hidden' name='action' value='create-password'>                <input type='hidden' name='user_id' value='<?=$_GET['user_id'];?>'>                                <div class="form-group">                   <span class="form-icon"><i class="fa fa-envelope" aria-hidden="true"></i></span>                    <input type="password" class="form-control"   placeholder="Enter new password" name="password" required>                </div>                <div class="form-group">                    <span class="form-icon"><i class="fa fa-lock" aria-hidden="true"></i></span>                    <input type="text" class="form-control" name="conf_password" id="pass" placeholder="Confirm password" required>                </div>                               <div class="form-group text-center"><button type="submit" name="submit" class="btn btn-default">Submit</button>                <div class='clearfix'><br></div>                </div>                            </form>                              </div>	      </div>    </div>             </div><script src="//ajax.googleapis.com/ajax/libs/jquery/2.0.3/jquery.min.js"></script><script>$('#form111').submit(function(event){        event.preventDefault();                 $('#response-success').html("<b>Loading response...</b>");                 $.ajax({            type: 'POST',            dataType : "json",            url: "<?=$configs['vpath']?>ajax-home",             data: new FormData(this),    		contentType: false,       // The content type used when sending data to the server.			cache: false,             // To unable request pages to be cached			processData:false           })        .done(function(data)        {        	//alert(data);            $('#response').html(data.msg);            $('#pending').html(data.pending);            $('#list').html(data.list);            if(data.error)             {            	 $('#response-error').html(data.error);            	 $('#response-success').html("");            }            if(data.success)             {            	 $('#form111').html(data.success);            	 $('#response-error').html("");            	 $('#response-success').html("");            }					if(data.url)			{				window.location=data.url;         			}                })        .fail(function()         {                     // just in case posting your form failed            alert("Posting failed.");                     });         // to prevent refreshing the whole page page        return false;     });	</script> 